style.css:
/* Background color for the body */
body {
  background-color: #ADD8E6; /* Light Blue */
  color: #FFFF00; /* Yellow text */
}

/* Navigation bar */
nav {
  background-color: #ADD8E6; /* Light Blue */
  color: #FFFF00; /* Yellow text */
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  color: #FFFF00; /* Yellow text */
}

/* Links */
a {
  color: #FFD700; /* Gold */
}

a:hover {
  color: #FFA500; /* Orange */
}

/* Buttons */
button {
  background-color: #ADD8E6; /* Light Blue */
  color: #FFFF00; /* Yellow text */
  border: none;
}

button:hover {
  background-color: #B0E0E6; /* Powder Blue */
}

/* Inputs */
input, textarea {
  background-color: #87CEEB; /* Sky Blue */
  color: #FFFF00; /* Yellow text */
  border: 1px solid #FFFF00; /* Yellow border */
}

input::placeholder, textarea::placeholder {
  color: #FFD700; /* Gold */
}
